1	import { Prisma } from "@prisma/client";
2	import { db } from "@/lib/db";
3	import { classifyError, FAMILIES, type FamilyId } from "./errors";
4	
5	// Every query here is a groupBy, an aggregate, or one grouped raw statement
6	// with bound parameters. Nothing runs inside a loop over rows — the same rule
7	// app/admin/users/page.tsx follows. The one findMany is bounded by `take` and
8	// selects three columns, because error text has to be classified in TypeScript
9	// (the family rules are regexes, and pushing them into SQL would put the
10	// vocabulary in two places).
11	
12	export const WINDOWS = {
13	  "24h": { label: "24 hours", hours: 24, unit: "hour" as const },
14	  "7d": { label: "7 days", hours: 24 * 7, unit: "day" as const },
15	  "30d": { label: "30 days", hours: 24 * 30, unit: "day" as const },
16	  "90d": { label: "90 days", hours: 24 * 90, unit: "day" as const },
17	};
18	
19	export type WindowKey = keyof typeof WINDOWS;
20	
21	export function isWindowKey(v: unknown): v is WindowKey {
22	  return typeof v === "string" && v in WINDOWS;
23	}
24	
25	/** How many failures are pulled back for classification in one query. */
26	const FAILURE_SAMPLE_CAP = 2000;
27	
28	/** A RUNNING build older than this is not running, it is abandoned. */
29	export const STUCK_AFTER_MS = 15 * 60 * 1000;
30	
31	export type Bucket = {
32	  start: Date;
33	  total: number;
34	  succeeded: number;
35	  failed: number;
36	  running: number;
37	};
38	
39	type BucketRow = {
40	  bucket: Date;
41	  total: number;
42	  succeeded: number;
43	  failed: number;
44	  running: number;
45	};
46	
47	type TimingRow = {
48	  status: string;
49	  n: number;
50	  p50: number | null;
51	  p95: number | null;
52	  max: number | null;
53	};
54	
55	export type Timing = { status: string; n: number; p50: number | null; p95: number | null; max: number | null };
56	
57	export type FamilyStat = {
58	  id: FamilyId;
59	  count: number;
60	  /** Share of all classified failures in the window. */
61	  share: number;
62	  /** Count within the recent half of the window. */
63	  recent: number;
64	  /** Share of failures within the recent half. Null when that half had none. */
65	  recentShare: number | null;
66	  lastSeen: Date | null;
67	  /** Most recent raw error in this family — collapsed and truncated before render. */
68	  sample: string;
69	};
70	
71	export type HealthData = {
72	  since: Date;
73	  now: Date;
74	  midpoint: Date;
75	  unit: "hour" | "day";
76	
77	  totalAllTime: number;
78	  total: number;
79	  succeeded: number;
80	  failed: number;
81	  running: number;
82	  stuck: number;
83	
84	  buckets: Bucket[];
85	  peakFailureRate: { rate: number; start: Date } | null;
86	
87	  families: FamilyStat[];
88	  failuresTotal: number;
89	  failuresSampled: number;
90	
91	  timings: Timing[];
92	  repairs: { attempts: number; count: number }[];
93	  repaired: number;
94	  succeededFirstTry: number;
95	
96	  costMicros: number;
97	  sdkStampedBuilds: number;
98	};
99	
100	function bucketStarts(since: Date, now: Date, unit: "hour" | "day"): Date[] {
101	  const stepMs = unit === "hour" ? 3_600_000 : 86_400_000;
102	  // Align to a UTC boundary so these line up with Postgres date_trunc, which
103	  // truncates the stored (UTC) timestamp.
104	  const first = Math.floor(since.getTime() / stepMs) * stepMs;
105	  const last = Math.floor(now.getTime() / stepMs) * stepMs;
106	  const out: Date[] = [];
107	  for (let t = first; t <= last; t += stepMs) out.push(new Date(t));
108	  return out;
109	}
110	
111	export async function loadHealthData(windowKey: WindowKey): Promise<HealthData> {
112	  const cfg = WINDOWS[windowKey];
113	  const now = new Date();
114	  const since = new Date(now.getTime() - cfg.hours * 3_600_000);
115	  const midpoint = new Date(since.getTime() + (now.getTime() - since.getTime()) / 2);
116	  const stuckBefore = new Date(now.getTime() - STUCK_AFTER_MS);
117	
118	  const inWindow = { createdAt: { gte: since } };
119	
120	  // Two literal statements rather than one with the unit bound in, so the
121	  // truncation unit is never string-interpolated into SQL under any code path.
122	  const bucketRows: BucketRow[] =
123	    cfg.unit === "hour"
124	      ? await db.$queryRaw<BucketRow[]>`
125	          SELECT date_trunc('hour', b."createdAt") AS "bucket",
126	                 COUNT(*)::int AS "total",
127	                 COUNT(*) FILTER (WHERE b."status" = 'SUCCEEDED')::int AS "succeeded",
128	                 COUNT(*) FILTER (WHERE b."status" = 'FAILED')::int AS "failed",
129	                 COUNT(*) FILTER (WHERE b."status" NOT IN ('SUCCEEDED', 'FAILED'))::int AS "running"
130	          FROM "Build" b
131	          WHERE b."createdAt" >= ${since}
132	          GROUP BY 1
133	          ORDER BY 1`
134	      : await db.$queryRaw<BucketRow[]>`
135	          SELECT date_trunc('day', b."createdAt") AS "bucket",
136	                 COUNT(*)::int AS "total",
137	                 COUNT(*) FILTER (WHERE b."status" = 'SUCCEEDED')::int AS "succeeded",
138	                 COUNT(*) FILTER (WHERE b."status" = 'FAILED')::int AS "failed",
139	                 COUNT(*) FILTER (WHERE b."status" NOT IN ('SUCCEEDED', 'FAILED'))::int AS "running"
140	          FROM "Build" b
141	          WHERE b."createdAt" >= ${since}
142	          GROUP BY 1
143	          ORDER BY 1`;
144	
145	  const [
146	    totalAllTime,
147	    statusCounts,
148	    stuck,
149	    failuresTotal,
150	    failureRows,
151	    timingRows,
152	    repairRows,
153	    succeededFirstTry,
154	    costTotals,
155	    sdkStampedBuilds,
156	  ] = await Promise.all([
157	    db.build.count(),
158	    db.build.groupBy({ by: ["status"], where: inWindow, _count: { _all: true } }),
159	    db.build.count({
160	      where: { status: { notIn: ["SUCCEEDED", "FAILED"] }, createdAt: { lt: stuckBefore } },
161	    }),
162	    db.build.count({ where: { ...inWindow, status: "FAILED" } }),
163	    db.build.findMany({
164	      where: { ...inWindow, status: "FAILED" },
165	      select: { error: true, createdAt: true },
166	      orderBy: { createdAt: "desc" },
167	      take: FAILURE_SAMPLE_CAP,
168	    }),
169	    // Duration comes from the two timestamps rather than a stored field, so
170	    // it has to be defended: endedAt is null while a build is in flight, and
171	    // clock skew between the two writes has produced at least one row in this
172	    // database where endedAt is 2ms BEFORE createdAt. A negative duration in
173	    // a percentile is worse than a missing one.
174	    db.$queryRaw<TimingRow[]>`
175	      SELECT b."status",
176	             COUNT(*)::int AS "n",
177	             percentile_cont(0.5) WITHIN GROUP (
178	               ORDER BY (EXTRACT(EPOCH FROM (b."endedAt" - b."createdAt")) * 1000)::float8
179	             ) AS "p50",
180	             percentile_cont(0.95) WITHIN GROUP (
181	               ORDER BY (EXTRACT(EPOCH FROM (b."endedAt" - b."createdAt")) * 1000)::float8
182	             ) AS "p95",
183	             MAX((EXTRACT(EPOCH FROM (b."endedAt" - b."createdAt")) * 1000)::float8) AS "max"
184	      FROM "Build" b
185	      WHERE b."createdAt" >= ${since}
186	        AND b."endedAt" IS NOT NULL
187	        AND b."endedAt" >= b."createdAt"
188	      GROUP BY b."status"
189	      ORDER BY b."status"`,
190	    db.build.groupBy({
191	      by: ["repairAttempts"],
192	      where: inWindow,
193	      _count: { _all: true },
194	      orderBy: { repairAttempts: "asc" },
195	    }),
196	    db.build.count({ where: { ...inWindow, status: "SUCCEEDED", repairAttempts: 0 } }),
197	    db.build.aggregate({ where: inWindow, _sum: { costMicros: true } }),
198	    // The only rows that PROVE they came from the subscription engine. See the
199	    // caveat rendered on the page: this is a floor, not the true count.
200	    db.build.count({ where: { ...inWindow, model: "claude-agent-sdk-subscription" } }),
201	  ]);
202	
203	  const succeeded = statusCounts.find((s) => s.status === "SUCCEEDED")?._count._all ?? 0;
204	  const failed = statusCounts.find((s) => s.status === "FAILED")?._count._all ?? 0;
205	  const total = statusCounts.reduce((acc, s) => acc + s._count._all, 0);
206	  const running = total - succeeded - failed;
207	
208	  // Fill the gaps so the x-axis is real time, not "hours that happened to have
209	  // a build". A quiet stretch is information.
210	  const byBucket = new Map(bucketRows.map((r) => [r.bucket.getTime(), r]));
211	  const buckets: Bucket[] = bucketStarts(since, now, cfg.unit).map((start) => {
212	    const r = byBucket.get(start.getTime());
213	    return {
214	      start,
215	      total: r ? Number(r.total) : 0,
216	      succeeded: r ? Number(r.succeeded) : 0,
217	      failed: r ? Number(r.failed) : 0,
218	      running: r ? Number(r.running) : 0,
219	    };
220	  });
221	
222	  let peakFailureRate: { rate: number; start: Date } | null = null;
223	  for (const b of buckets) {
224	    const finished = b.succeeded + b.failed;
225	    if (finished === 0) continue;
226	    const rate = (b.failed / finished) * 100;
227	    if (!peakFailureRate || rate > peakFailureRate.rate) {
228	      peakFailureRate = { rate, start: b.start };
229	    }
230	  }
231	
232	  // ── Clustering ────────────────────────────────────────────────────────
233	  const counts = new Map<FamilyId, FamilyStat>();
234	  for (const f of FAMILIES) {
235	    counts.set(f.id, {
236	      id: f.id,
237	      count: 0,
238	      share: 0,
239	      recent: 0,
240	      recentShare: null,
241	      lastSeen: null,
242	      sample: "",
243	    });
244	  }
245	  let recentTotal = 0;
246	  for (const row of failureRows) {
247	    const id = classifyError(row.error);
248	    const stat = counts.get(id);
249	    if (!stat) continue;
250	    stat.count += 1;
251	    // failureRows is ordered newest-first, so the first row a family sees is
252	    // its most recent one.
253	    if (!stat.lastSeen) {
254	      stat.lastSeen = row.createdAt;
255	      stat.sample = row.error ?? "(no error text recorded)";
256	    }
257	    if (row.createdAt >= midpoint) {
258	      stat.recent += 1;
259	      recentTotal += 1;
260	    }
261	  }
262	
263	  const sampled = failureRows.length;
264	  const families = [...counts.values()]
265	    .filter((f) => f.count > 0)
266	    .map((f) => ({
267	      ...f,
268	      share: sampled === 0 ? 0 : (f.count / sampled) * 100,
269	      recentShare: recentTotal === 0 ? null : (f.recent / recentTotal) * 100,
270	    }))
271	    .sort((a, b) => b.count - a.count || a.id.localeCompare(b.id));
272	
273	  return {
274	    since,
275	    now,
276	    midpoint,
277	    unit: cfg.unit,
278	    totalAllTime,
279	    total,
280	    succeeded,
281	    failed,
282	    running,
283	    stuck,
284	    buckets,
285	    peakFailureRate,
286	    families,
287	    failuresTotal,
288	    failuresSampled: sampled,
289	    timings: timingRows.map((t) => ({
290	      status: t.status,
291	      n: Number(t.n),
292	      p50: t.p50 === null ? null : Number(t.p50),
293	      p95: t.p95 === null ? null : Number(t.p95),
294	      max: t.max === null ? null : Number(t.max),
295	    })),
296	    repairs: repairRows.map((r) => ({ attempts: r.repairAttempts, count: r._count._all })),
297	    repaired: repairRows.reduce((acc, r) => acc + (r.repairAttempts > 0 ? r._count._all : 0), 0),
298	    succeededFirstTry,
299	    costMicros: costTotals._sum.costMicros ?? 0,
300	    sdkStampedBuilds,
301	  };
302	}
303	
304	// Re-exported so page.tsx can narrow a caught Prisma error without importing
305	// the client itself.
306	export function isPrismaError(e: unknown): boolean {
307	  return (
308	    e instanceof Prisma.PrismaClientKnownRequestError ||
309	    e instanceof Prisma.PrismaClientInitializationError ||
310	    e instanceof Prisma.PrismaClientUnknownRequestError
311	  );
312	}
