1	import { access } from "node:fs/promises";
2	import path from "node:path";
3	import { db } from "@/lib/db";
4	import { ENGINE } from "@/lib/agent";
5	import { isMailConfigured } from "@/lib/mail";
6	import { billingEnabled } from "@/lib/stripe";
7	
8	// Dependency checks for /admin/health.
9	//
10	// SECRETS RULE, enforced by construction: every field below is a boolean, a
11	// duration, or a hand-written sentence. The only place an environment
12	// variable appears is in `env`, which holds NAMES. Nothing here ever reads a
13	// value into a string that reaches the page — not truncated, not masked. A
14	// masked secret is still a secret leak with extra steps, and an admin panel
15	// that prints "sk-ant-…f3a2" has put a fingerprint of the key in every
16	// screenshot of it.
17	//
18	// app/api/health/route.ts stays the LIVENESS probe: it answers "is the
19	// process up" with no dependencies, which is what a load balancer needs and
20	// what makes it safe to be unauthenticated. This module is the readiness
21	// view — it deliberately touches the things that probe must not.
22	
23	export type CheckStatus = "ok" | "fail" | "warn" | "unknown";
24	
25	export type Check = {
26	  id: string;
27	  label: string;
28	  status: CheckStatus;
29	  /** Names and booleans only — never a secret value. */
30	  detail: string;
31	  /** Environment variable NAMES this check reads. Values are never rendered. */
32	  env: string[];
33	};
34	
35	/**
36	 * Mirrors lib/build-site.ts, which does not export it. If that default ever
37	 * changes, this line has to change with it — and the mismatch would show up
38	 * here as a check that disagrees with reality, which is the failure mode this
39	 * page exists to make visible.
40	 */
41	const FOUNDATION_DIR = process.env.KODELY_FOUNDATION_DIR ?? "/home/kodely/kodely-foundation";
42	const FOUNDATION_DIR_SET = Boolean(process.env.KODELY_FOUNDATION_DIR);
43	
44	async function exists(p: string): Promise<boolean> {
45	  try {
46	    await access(p);
47	    return true;
48	  } catch {
49	    return false;
50	  }
51	}
52	
53	export type DatabaseCheck = Check & { latencyMs: number | null };
54	
55	/**
56	 * The one check that has to work when nothing else does. Every other panel on
57	 * the page is a query against this connection, so the page runs this first
58	 * and degrades to checks-only if it fails, rather than throwing a 500 at the
59	 * exact moment an operator is trying to find out what is wrong.
60	 */
61	export async function checkDatabase(): Promise<DatabaseCheck> {
62	  const started = Date.now();
63	  try {
64	    await db.$queryRaw`SELECT 1`;
65	    const latencyMs = Date.now() - started;
66	    return {
67	      id: "database",
68	      label: "Database reachable",
69	      status: latencyMs > 1000 ? "warn" : "ok",
70	      detail:
71	        latencyMs > 1000
72	          ? `SELECT 1 answered in ${latencyMs}ms — slow enough to be worth looking at.`
73	          : `SELECT 1 answered in ${latencyMs}ms.`,
74	      env: ["DATABASE_URL"],
75	      latencyMs,
76	    };
77	  } catch {
78	    return {
79	      id: "database",
80	      label: "Database reachable",
81	      status: "fail",
82	      // The driver's message can carry the connection string, so it is
83	      // deliberately swallowed rather than surfaced.
84	      detail:
85	        "SELECT 1 failed. The error is withheld here because a Postgres connection error can echo the DSN — read it from the server log.",
86	      env: ["DATABASE_URL"],
87	      latencyMs: null,
88	    };
89	  }
90	}
91	
92	/**
93	 * The foundation tree is the shared, pre-installed node_modules every build
94	 * symlinks against instead of running `npm install` per generation. When it is
95	 * absent, vite fails with "Cannot find module", which reads like a bug in the
96	 * generated site and is not — this has cost debugging time twice.
97	 *
98	 * Three separate checks rather than one, because "the directory is there" is
99	 * not the question: the question is whether the exact entrypoint
100	 * lib/build-site.ts spawns is on disk.
101	 */
102	export async function checkFoundation(): Promise<Check[]> {
103	  const dirOk = await exists(FOUNDATION_DIR);
104	  const modulesOk = dirOk && (await exists(path.join(FOUNDATION_DIR, "node_modules")));
105	  const viteOk =
106	    modulesOk &&
107	    (await exists(path.join(FOUNDATION_DIR, "node_modules", "vite", "bin", "vite.js")));
108	
109	  return [
110	    {
111	      id: "foundation-dir",
112	      label: "Foundation directory",
113	      status: dirOk ? "ok" : "fail",
114	      detail: dirOk
115	        ? FOUNDATION_DIR_SET
116	          ? "Present. KODELY_FOUNDATION_DIR is set and the path it names exists."
117	          : "Present, but KODELY_FOUNDATION_DIR is unset — this is the built-in Linux default path, which is wrong on a Windows host."
118	        : FOUNDATION_DIR_SET
119	          ? "Missing. KODELY_FOUNDATION_DIR is set but names a path that does not exist."
120	          : "Missing, and KODELY_FOUNDATION_DIR is unset, so lib/build-site.ts fell back to its Linux default path. On Windows that resolves under the drive root and every build fails at the symlink step.",
121	      env: ["KODELY_FOUNDATION_DIR"],
122	    },
123	    {
124	      id: "foundation-modules",
125	      label: "Foundation node_modules",
126	      status: modulesOk ? "ok" : "fail",
127	      detail: modulesOk
128	        ? "Present. Builds symlink this tree instead of installing per generation."
129	        : "Missing. Every build will fail with a misleading “Cannot find module”. Re-run scripts/install-foundation.mjs on this host.",
130	      env: ["KODELY_FOUNDATION_DIR"],
131	    },
132	    {
133	      id: "foundation-vite",
134	      label: "Vite entrypoint",
135	      status: viteOk ? "ok" : "fail",
136	      detail: viteOk
137	        ? "node_modules/vite/bin/vite.js is on disk — the exact file lib/build-site.ts spawns."
138	        : "node_modules/vite/bin/vite.js is absent. A node_modules directory that exists but is incomplete fails the same way as no directory at all.",
139	      env: [],
140	    },
141	  ];
142	}
143	
144	export type EngineCheck = {
145	  engine: "api" | "sdk";
146	  /** True when recorded costMicros are imputed from a rate card rather than billed. */
147	  costsImputed: boolean;
148	  credentials: Check;
149	};
150	
151	/**
152	 * Which generation engine is live, and whether it can authenticate.
153	 *
154	 * The credential check re-derives assertSdkCredentials() from lib/agent-sdk.ts
155	 * (which is private to that module) rather than importing it: importing
156	 * lib/agent-sdk.ts for its side effects would delete ANTHROPIC_API_KEY from
157	 * this process, which is a mutation an admin page has no business performing.
158	 */
159	export async function checkEngine(): Promise<EngineCheck> {
160	  if (ENGINE === "sdk") {
161	    const home = process.env.HOME ?? process.env.USERPROFILE;
162	    const hasToken = Boolean(process.env.CLAUDE_CODE_OAUTH_TOKEN);
163	    const hasCredentialsFile =
164	      Boolean(home) && (await exists(path.join(home as string, ".claude", ".credentials.json")));
165	    const ok = hasToken || hasCredentialsFile;
166	
167	    return {
168	      engine: "sdk",
169	      costsImputed: true,
170	      credentials: {
171	        id: "engine-credentials",
172	        label: "SDK subscription credentials",
173	        status: ok ? "ok" : "fail",
174	        detail: ok
175	          ? hasToken
176	            ? "CLAUDE_CODE_OAUTH_TOKEN is set. Presence only — an expired or revoked token reads as OK here and shows up above as an SDK-auth failure family."
177	            : "A ~/.claude/.credentials.json written by `claude setup-token` is present for the user running this process. Presence only — a stale login reads as OK here and shows up above as an SDK-auth failure family."
178	          : "Neither CLAUDE_CODE_OAUTH_TOKEN nor ~/.claude/.credentials.json is present, so every generation will fail with “Not logged in” before reaching the model. There is deliberately no fallback to the metered API engine.",
179	        env: ["CLAUDE_CODE_OAUTH_TOKEN"],
180	      },
181	    };
182	  }
183	
184	  const hasKey = Boolean(process.env.ANTHROPIC_API_KEY);
185	  return {
186	    engine: "api",
187	    costsImputed: false,
188	    credentials: {
189	      id: "engine-credentials",
190	      label: "Anthropic API key",
191	      status: hasKey ? "ok" : "fail",
192	      detail: hasKey
193	        ? "ANTHROPIC_API_KEY is set. Presence only — nothing here validates it against the API."
194	        : "ANTHROPIC_API_KEY is unset. The metered engine cannot start a generation.",
195	      env: ["ANTHROPIC_API_KEY"],
196	    },
197	  };
198	}
199	
200	/** SMTP and Stripe both follow the "inert until configured" shape, so absent is a state, not an error. */
201	export function checkIntegrations(): Check[] {
202	  const mail = isMailConfigured();
203	  const stripe = billingEnabled();
204	
205	  return [
206	    {
207	      id: "smtp",
208	      label: "SMTP configured",
209	      status: mail ? "ok" : "warn",
210	      detail: mail
211	        ? "Host, user and password are all set. Presence only — no connection is attempted from this page."
212	        : "Not configured. lib/mail.ts stays inert and callers return a clean 503, so transactional mail (welcome, low credits, build failed) silently does not send.",
213	      env: ["SMTP_HOST", "SMTP_PORT", "SMTP_USER", "SMTP_PASS", "MAIL_FROM"],
214	    },
215	    {
216	      id: "stripe",
217	      label: "Stripe configured",
218	      status: stripe ? "ok" : "warn",
219	      detail: stripe
220	        ? "Secret key and webhook secret are both set. Presence only — no call is made to Stripe."
221	        : "Not configured. Billing degrades gracefully and nobody can top up credits.",
222	      env: ["STRIPE_SECRET_KEY", "STRIPE_WEBHOOK_SECRET"],
223	    },
224	  ];
225	}
