466	      footnote={
467	        data.peakFailureRate
468	          ? `Worst ${data.unit}: ${formatPct(data.peakFailureRate.rate)} failure rate at ${stamp(data.peakFailureRate.start)} UTC.`
469	          : `No finished builds in this window.`
470	      }
