525	function bucketTitle(b: Bucket, unit: "hour" | "day"): string {
526	  const when = unit === "hour" ? `${stamp(b.start)} UTC` : b.start.toISOString().slice(0, 10);
527	  const finished = b.succeeded + b.failed;
528	  const rate = pct(b.failed, finished);
529	  return `${when} — ${b.total} build${b.total === 1 ? "" : "s"}: ${b.succeeded} succeeded, ${b.failed} failed${b.running ? `, ${b.running} running` : ""}${rate === null ? "" : ` (${rate}% failure rate)`}`;
530	}
531	
532	function chartSummary(data: HealthData): string {
533	  return `Builds per ${data.unit}: ${data.succeeded} succeeded and ${data.failed} failed across ${data.buckets.length} ${data.unit}s.`;
534	}
