538	const TIMING_ORDER = ["SUCCEEDED", "FAILED"];
539	
540	function Timings({ data }: { data: HealthData }) {
541	  const rows = [...data.timings].sort(
542	    (a, b) => TIMING_ORDER.indexOf(a.status) - TIMING_ORDER.indexOf(b.status),
543	  );
544	  const succ = rows.find((r) => r.status === "SUCCEEDED");
545	  const fail = rows.find((r) => r.status === "FAILED");
546	  // A failure that comes back an order of magnitude faster than a success did
547	  // not fail at generation — it never got there.
548	  const failFast = succ?.p50 != null && fail?.p50 != null && fail.p50 * 5 < succ.p50;
549	
550	  return (
551	    <Panel
552	      title="Build duration"
553	      subtitle="From createdAt to endedAt, split by outcome. Rows still in flight, and the occasional row whose endedAt precedes its createdAt, are excluded."
554	      footnote={
555	        <>
556	          {failFast ? (
557	            <>
558	              Failures are returning far faster than successes, which means they are failing before
559	              the model does any work — a configuration or credential problem, not a generation
560	              one.{" "}
561	            </>
562	          ) : null}
563	          The vite step inside a build is separately bounded at 60s by lib/build-site.ts; these
564	          figures cover the whole generation, so they are not comparable to that bound.
565	        </>
566	      }
567	    >
568	      {rows.length === 0 ? (
569	        <PanelEmpty>No finished builds with usable timestamps in this window.</PanelEmpty>
570	      ) : (
571	        <TableFrame>
572	          <thead>
573	            <tr className="border-b border-black/10 text-xs text-black/50 dark:border-white/10 dark:text-white/50">
574	              <Th>Outcome</Th>
575	              <Th align="right">n</Th>
576	              <Th align="right">p50</Th>
577	              <Th align="right">p95</Th>
578	              <Th align="right">max</Th>
579	            </tr>
580	          </thead>
581	          <tbody className="divide-y divide-black/10 dark:divide-white/10">
582	            {rows.map((r) => (
583	              <tr key={r.status}>
584	                <td
585	                  className={`px-4 py-2 font-medium ${
586	                    r.status === "SUCCEEDED"
587	                      ? "text-emerald-600 dark:text-emerald-400"
588	                      : r.status === "FAILED"
589	                        ? "text-red-600 dark:text-red-400"
590	                        : "text-black/40 dark:text-white/40"
591	                  }`}
592	                >
593	                  {r.status}
594	                </td>
595	                <td className="px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
596	                  {r.n}
597	                </td>
598	                <td className="px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
599	                  {formatDuration(r.p50)}
600	                </td>
601	                <td className="px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
602	                  {formatDuration(r.p95)}
603	                </td>
604	                <td className="px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
605	                  {formatDuration(r.max)}
606	                </td>
607	              </tr>
608	            ))}
609	          </tbody>
610	        </TableFrame>
611	      )}
612	    </Panel>
613	  );
614	}
