618	function Repairs({ data }: { data: HealthData }) {
619	  const repairRate = pct(data.repaired, data.total);
620	  const firstTry = pct(data.succeededFirstTry, data.succeeded);
621	  const maxCount = data.repairs.reduce((m, r) => Math.max(m, r.count), 0);
