13	export function truncate(text: string, max = 60): string {
14	  return text.length > max ? `${text.slice(0, max)}…` : text;
15	}
16	
17	/**
18	 * Error text is multi-line and can contain fragments of a customer's source
19	 * code. Collapse it to a single line before it is ever rendered, then cut it
20	 * short — a list view is for recognising a shape, not for reading a log.
21	 */
22	export function oneLine(text: string, max = 150): string {
23	  return truncate(text.replace(/\s+/g, " ").trim(), max);
24	}
25	
26	export function formatDuration(ms: number | null): string {
27	  if (ms === null || !Number.isFinite(ms)) return "—";
28	  if (ms < 1000) return `${Math.round(ms)}ms`;
29	  if (ms < 60_000) return `${(ms / 1000).toFixed(1)}s`;
30	  const m = Math.floor(ms / 60_000);
31	  const s = Math.round((ms % 60_000) / 1000);
32	  return `${m}m ${String(s).padStart(2, "0")}s`;
33	}
34	
35	export function formatUsd(micros: number, decimals = 2): string {
36	  return `$${(micros / 1_000_000).toFixed(decimals)}`;
37	}
38	
39	export function pct(n: number, d: number): number | null {
40	  if (d <= 0) return null;
41	  return Math.round((n / d) * 1000) / 10;
42	}
43	
44	export function formatPct(v: number | null): string {
45	  return v === null ? "—" : `${v.toFixed(1)}%`;
46	}
